-- Gen2Rev challenge ingest: Psalms (World 19) and Proverbs (World 20) -- EASY and HARD tiers
-- Generated from docs/content/psalms-easy.md, docs/content/psalms-hard.md,
--   docs/content/proverbs-easy.md, docs/content/proverbs-hard.md
-- All four briefs: theological review approved / approved-with-changes, independent verbatim-text QA
--   pass complete (docs/CONTENT_REVIEW_LOG.md rows 19e/19h/20e/20h, docs/QA_SIGNOFF.md same rows;
--   docs/reviews/psalms-easy-review.md, docs/reviews/psalms-hard-review.md,
--   docs/reviews/proverbs-easy-review.md, docs/reviews/proverbs-hard-review.md).
-- Medium-tier rows (difficulty_tier = 'medium') already in the DB from docs/ingest/job-psalms.sql and
--   docs/ingest/proverbs-ecclesiastes-song-of-solomon.sql are untouched by this file.
--
-- Structural rules carried forward from each medium brief and reaffirmed/extended by the easy/hard
-- briefs:
--   Psalms: imprecatory psalms, Psalm 22, Psalm 110, and Psalm 51:5 excluded entirely in every tier.
--     Psalm 51:12 ("the joy of your salvation," hard item 6) is recall-only, word-level-only -- never
--     a question about what "salvation" refers to or a doctrine of salvation.
--   Proverbs: Proverbs 22:6 restricted to recall/attribution-matching format only, never
--     application-framed; the Proverbs 31:10-31 cluster restricted to recall of the poem's own wording
--     only. Proverbs 3:7-8 (hard item 2) and Proverbs 16:9 (hard item 6) are recall-only, never
--     multiple choice or a question resolving the underlying interpretive tension.
--   difficulty_rank: 1 for every easy-tier row, 5 for every hard-tier row (medium rows, untouched,
--     keep their own varied ranks).

with w as (select id from public.world where book_slug = 'psalms')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  -- ===================== PSALMS — EASY TIER =====================
  ((select id from w), 'multiple_choice', 'According to Psalm 1:1, whose counsel does the blessed man not walk in?',
   'Psalm 1:1', 'Blessed is the man who doesn''t walk in the counsel of the wicked, nor stand on the path of sinners, nor sit in the seat of scoffers;', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["the wicked", "the priests", "the elders", "the poor"], "correct_index": 0}', false, 1),
  ((select id from w), 'multiple_choice', 'According to Psalm 1:3, the righteous person is compared to what?',
   'Psalm 1:3', 'He will be like a tree planted by the streams of water, that produces its fruit in its season, whose leaf also does not wither. Whatever he does shall prosper.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["a tree planted by streams of water", "a mountain", "a lamp", "a shield"], "correct_index": 0}', false, 2),
  ((select id from w), 'multiple_choice', 'According to Psalm 23:1, what does the psalmist call Yahweh?',
   'Psalm 23:1', 'Yahweh is my shepherd; I shall lack nothing.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["my shepherd", "my king", "my rock", "my father"], "correct_index": 0}', false, 3),
  ((select id from w), 'multiple_choice', 'Per its own superscription, who is traditionally credited as the author of Psalm 23?',
   'Psalm 23, superscription', 'A Psalm by David.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["David", "Solomon", "Moses", "Asaph"], "correct_index": 0}', false, 4),
  ((select id from w), 'multiple_choice', 'According to Psalm 23:2, where does Yahweh make the psalmist lie down?',
   'Psalm 23:2', 'He makes me lie down in green pastures. He leads me beside still waters.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["green pastures", "a mountain top", "a desert", "a garden"], "correct_index": 0}', false, 5),
  ((select id from w), 'recall', 'Fill in the missing word: what does David ask God to create in him, per Psalm 51:10?',
   'Psalm 51:10', 'Create in me a clean heart, O God. Renew a right spirit within me.', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "Create in me a clean ___, O God. Renew a right spirit within me.", "answer": "heart"}', false, 6),
  ((select id from w), 'multiple_choice', 'Per Psalm 51''s own superscription, which prophet came to David?',
   'Psalm 51, superscription', 'For the Chief Musician. A Psalm by David, when Nathan the prophet came to him, after he had gone in to Bathsheba.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Nathan", "Samuel", "Elijah", "Gad"], "correct_index": 0}', false, 7),
  ((select id from w), 'multiple_choice', 'Psalm 100 opens with a call to do what?',
   'Psalm 100:1', 'Shout for joy to Yahweh, all you lands!', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Shout for joy to Yahweh", "Sit in silence", "Weep before Yahweh", "Build an altar"], "correct_index": 0}', false, 8),
  ((select id from w), 'multiple_choice', 'According to Psalm 100:3, whose people are we called?',
   'Psalm 100:3', 'Know that Yahweh, he is God. It is he who has made us, and we are his. We are his people, and the sheep of his pasture.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["his (Yahweh''s) people", "the king''s people", "the priest''s people", "no one''s"], "correct_index": 0}', false, 9),
  ((select id from w), 'multiple_choice', 'According to Psalm 121, where does the psalmist''s help come from?',
   'Psalm 121:1-2', 'I will lift up my eyes to the hills. Where does my help come from? My help comes from Yahweh, who made heaven and earth.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Yahweh, who made heaven and earth", "the hills themselves", "the king", "the priests"], "correct_index": 0}', false, 10),
  ((select id from w), 'multiple_choice', 'According to Psalm 121:4, what will the keeper of Israel never do?',
   'Psalm 121:4', 'Behold, he who keeps Israel will neither slumber nor sleep.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["slumber nor sleep", "eat nor drink", "speak nor sing", "rest nor gather"], "correct_index": 0}', false, 11),
  ((select id from w), 'multiple_choice', 'Which instrument is named first in Psalm 150:3?',
   'Psalm 150:3', 'Praise him with the sounding of the trumpet! Praise him with harp and lyre!', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["trumpet", "cymbals", "flute", "tambourine"], "correct_index": 0}', false, 12),
  ((select id from w), 'multiple_choice', 'According to Psalm 100:5, what does the text say endures forever?',
   'Psalm 100:5', 'For Yahweh is good. His loving kindness endures forever, his faithfulness to all generations.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["his loving kindness", "his temple", "his throne", "his covenant"], "correct_index": 0}', true, 13),
  ((select id from w), 'sequence', 'Put Psalm 150''s list of instruments in the order they appear in the text.',
   'Psalm 150:3-5', 'Praise him with the sounding of the trumpet! Praise him with harp and lyre!; Praise him with tambourine and dancing! Praise him with stringed instruments and flute!; Praise him with loud cymbals! Praise him with resounding cymbals!', 'WEB', 1, 'easy',
   '{"type": "sequence", "items": ["Trumpet, harp, and lyre (v.3)", "Tambourine and dancing, stringed instruments and flute (v.4)", "Loud cymbals and resounding cymbals (v.5)"], "correct_order": [0, 1, 2]}', true, 14),
  ((select id from w), 'multiple_choice', 'According to Psalm 150:6, what does the text call on everything that has breath to do?',
   'Psalm 150:6', 'Let everything that has breath praise Yah! Praise Yah!', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["praise Yah", "build an altar", "offer sacrifice", "keep silence"], "correct_index": 0}', true, 15),

