with w as (select id from public.world where book_slug = 'proverbs')
insert into public.challenge (world_id, type, prompt, verse_ref, verse_text, translation, difficulty_rank, difficulty_tier, answer_key, is_boss_item, sort_order)
values
  -- ===================== PROVERBS — EASY TIER =====================
  ((select id from w), 'multiple_choice', 'According to Proverbs 3:5, in what does the text say to trust?',
   'Proverbs 3:5-6', 'Trust in Yahweh with all your heart, and don''t lean on your own understanding. In all your ways acknowledge him, and he will make your paths straight.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Yahweh", "your own understanding", "riches", "the king"], "correct_index": 0}', false, 1),
  ((select id from w), 'multiple_choice', 'According to Proverbs 1:7, what is the beginning of knowledge?',
   'Proverbs 1:7', 'The fear of Yahweh is the beginning of knowledge, but the foolish despise wisdom and instruction.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["the fear of Yahweh", "wealth", "education", "age"], "correct_index": 0}', false, 2),
  ((select id from w), 'multiple_choice', 'Which verse says ''Train up a child in the way he should go''?',
   'Proverbs 22:6', 'Train up a child in the way he should go, and when he is old he will not depart from it.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Proverbs 22:6", "Proverbs 3:5", "Proverbs 1:7", "Proverbs 31:10"], "correct_index": 0}', false, 3),
  ((select id from w), 'multiple_choice', 'According to Proverbs 16:18, what goes before destruction?',
   'Proverbs 16:18', 'Pride goes before destruction, and an arrogant spirit before a fall.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Pride", "Wisdom", "Humility", "Patience"], "correct_index": 0}', false, 4),
  ((select id from w), 'multiple_choice', 'According to Proverbs 17:17, when is a brother born?',
   'Proverbs 17:17', 'A friend loves at all times; and a brother is born for adversity.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["for adversity", "for celebration", "for wealth", "for war"], "correct_index": 0}', false, 5),
  ((select id from w), 'multiple_choice', 'According to Proverbs 27:17, what does iron do to iron?',
   'Proverbs 27:17', 'Iron sharpens iron; so a man sharpens his friend''s countenance.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["sharpens it", "breaks it", "melts it", "bends it"], "correct_index": 0}', false, 6),
  ((select id from w), 'multiple_choice', 'According to Proverbs 31:30, what does the text call vain?',
   'Proverbs 31:30', 'Charm is deceitful, and beauty is vain; but a woman who fears Yahweh, she shall be praised.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["beauty", "wealth", "wisdom", "strength"], "correct_index": 0}', false, 7),
  ((select id from w), 'multiple_choice', 'According to Proverbs 3:13, what is the man called who finds wisdom?',
   'Proverbs 3:13', 'Happy is the man who finds wisdom, the man who gets understanding.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["Happy", "Rich", "Powerful", "Famous"], "correct_index": 0}', false, 8),
  ((select id from w), 'multiple_choice', 'According to Proverbs 4:23, what are you told to keep with all diligence?',
   'Proverbs 4:23', 'Keep your heart with all diligence, for out of it is the wellspring of life.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["your heart", "your money", "your land", "your name"], "correct_index": 0}', false, 9),
  ((select id from w), 'multiple_choice', 'According to Proverbs 4:18, the path of the righteous is compared to what?',
   'Proverbs 4:18', 'But the path of the righteous is like the dawning light that shines more and more until the perfect day.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["the dawning light", "a river", "a tree", "a lamp"], "correct_index": 0}', false, 10),
  ((select id from w), 'recall', 'Fill in the missing word: what a gentle answer turns away, per Proverbs 15:1.',
   'Proverbs 15:1', 'A gentle answer turns away wrath, but a harsh word stirs up anger.', 'WEB', 1, 'easy',
   '{"type": "recall", "template": "A gentle answer turns away ___, but a harsh word stirs up anger.", "answer": "wrath"}', true, 11),
  ((select id from w), 'sequence', 'Put these three quotations in the order they occur in the book of Proverbs.',
   'Proverbs 1:7; 3:5-6; 22:6', 'The fear of Yahweh is the beginning of knowledge, but the foolish despise wisdom and instruction.; Trust in Yahweh with all your heart, and don''t lean on your own understanding. In all your ways acknowledge him, and he will make your paths straight.; Train up a child in the way he should go, and when he is old he will not depart from it.', 'WEB', 1, 'easy',
   '{"type": "sequence", "items": ["“The fear of Yahweh is the beginning of knowledge...” (Proverbs 1:7)", "“Trust in Yahweh with all your heart...” (Proverbs 3:5-6)", "“Train up a child in the way he should go...” (Proverbs 22:6)"], "correct_order": [0, 1, 2]}', true, 12),
  ((select id from w), 'multiple_choice', 'According to Proverbs 22:1, what is more desirable than great riches?',
   'Proverbs 22:1', 'A good name is more desirable than great riches, and loving favor is better than silver and gold.', 'WEB', 1, 'easy',
   '{"type": "multiple_choice", "options": ["A good name", "Long life", "Many children", "Land"], "correct_index": 0}', true, 13),

